static constexpr int N = 64;
std::vector<Entity*> cells[N * N];

void insert(Entity* e) { cells[cell_y(e->y) * N + cell_x(e->x)].push_back(e); }

void near(float x, float y, float r, std::vector<Entity*>& out) {
    for (int cy = cell_y(y - r); cy <= cell_y(y + r); ++cy)
        for (int cx = cell_x(x - r); cx <= cell_x(x + r); ++cx)
            for (Entity* e : cells[cy * N + cx])
                if (dist2(e->pos, x, y) <= r * r) out.push_back(e);
}

